<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Staff login</title><style>body{font:16px system-ui;background:#f3f6fa;color:#172033;display:grid;place-items:center;min-height:100vh;margin:0}.card{background:white;padding:28px;border-radius:12px;width:min(95%,400px);box-shadow:0 3px 18px #0002}label{display:block;margin-top:16px}input{display:block;width:100%;box-sizing:border-box;padding:10px;margin-top:6px}button{background:#1c5abd;color:#fff;border:0;padding:11px 18px;margin-top:20px;border-radius:7px}.error{background:#ffe7e7;padding:10px}</style></head><body><div class="card"><h1>Staff login</h1><?php if (session()->getFlashdata('error')): ?><p class="error" role="alert"><?= esc(session()->getFlashdata('error')) ?></p><?php endif ?><form method="post" action="<?= site_url('login') ?>"><?= csrf_field() ?><label>Username<input name="username" maxlength="50" required autocomplete="username" value="<?= esc(old('username')) ?>"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button>Sign in</button></form></div></body></html>
